 static void NativeWorldIdentity(){string session="source-room",map=new string('b',64),canonical="r6-ground/weapon/1";string local=R24LanWorldIdentity.LocalId(session,map,"weapon",canonical,"awp",5);Need(local.Length<=128&&local!=canonical&&local==R24LanWorldIdentity.LocalId(session,map,"weapon",canonical,"awp",5),"Host lifetime has a stable separately scoped native identity");Need(local!=R24LanWorldIdentity.LocalId(session,map,"weapon",canonical,"px4",1)&&local!=R24LanWorldIdentity.LocalId(session,new string('c',64),"weapon",canonical,"awp",5),"Independent peer profile/rarity/map serials cannot alias the host lifetime");var actual=new Ashfall.Integration.Playable.HandsWeapons.R23RoundState(new string[0],new ReceiptPorts(),true);Need(actual.RegisterWeaponInstance(local,"awp",5)&&actual.SelectWeapon(local)&&actual.ReconcileNetworkAmmo(local,2,-1,-1,17)&&actual.ActiveLoaded==2&&actual.ActiveReserve==17,"Scoped host import owns actual native rarity/mechanics and accepts only its correction");Need(!actual.RegisterWeaponInstance(local,"px4",1),"Existing source instance cannot be reminted under a different profile");}
